    11	public final class ReservationService {
    12	
    13	    static final String HOTEL_NAME = "Pousada Maré Alta";
    14	
    15	    private final Rooms rooms;
    16	    private final ReservationStore store;
    17	    private final PriceCalculator priceCalculator;
    18	    private final List<ReservationEventListener> eventListeners;
    19	
    20	    public ReservationService(
    21	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
    22	        this.rooms = rooms;
    23	        this.store = store;
    24	        this.priceCalculator = priceCalculator;
    25	        this.eventListeners = List.of(
    26	                new GuestNotifier(emailSender),
    27	                new HousekeepingNotifier(emailSender),
    28	                new FinanceNotifier(emailSender));
    29	    }
    30	
    31	    public synchronized Reservation create(NewReservation request) {
    32	        if (!request.checkOut().isAfter(request.checkIn())) {
    33	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    34	        }
    35	        if (request.guests() < 1) {
    36	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    37	        }
    38	        Room room = rooms.find(request.roomNumber())
    39	                .orElseThrow(() -> new HotelException(
    40	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    41	        if (request.guests() > room.capacity()) {
    42	            throw new HotelException(
    43	                    ErrorCode.CAPACITY_EXCEEDED,
    44	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    45	        }
    46	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
    47	            throw new HotelException(
    48	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    49	        }
    50	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
    51	        return store.add(request, price);
    52	    }
    53	
    54	    public Reservation find(long reservationId) {
    55	        return store.find(reservationId)
    56	                .orElseThrow(() -> new HotelException(
    57	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    58	    }
    59	
    60	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
    61	    public synchronized Reservation confirm(long reservationId) {
    62	        Reservation reservation = find(reservationId);
    63	        if (reservation.status() != ReservationStatus.PENDING) {
    64	            throw notAllowed(reservation, "confirm");
    65	        }
    66	        reservation.confirmPayment();
    67	        store.update(reservation);
    68	        Room room = roomOf(reservation);
    69	        for (ReservationEventListener listener : eventListeners) {
    70	            listener.onConfirmed(reservation, room);
    71	        }
    72	        return reservation;
    73	    }
    74	
    75	    /**
    76	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
    77	     * reservation was never paid, so nothing comes back).
    78	     */
    79	    public synchronized Reservation cancel(long reservationId) {
    80	        Reservation reservation = find(reservationId);
    81	        if (reservation.status() != ReservationStatus.PENDING
    82	                && reservation.status() != ReservationStatus.CONFIRMED) {
    83	            throw notAllowed(reservation, "cancel");
    84	        }
    85	        BigDecimal refund = switch (reservation.ratePlan()) {
    86	            case STANDARD -> reservation.amountPaid();
    87	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
    88	        };
    89	        reservation.cancel(refund);
    90	        store.update(reservation);
    91	        Room room = roomOf(reservation);
    92	        for (ReservationEventListener listener : eventListeners) {
    93	            listener.onCancelled(reservation, room);
    94	        }
    95	        return reservation;
    96	    }
    97	
    98	    public synchronized Reservation checkIn(long reservationId) {
    99	        Reservation reservation = find(reservationId);
   100	        if (reservation.status() != ReservationStatus.CONFIRMED) {
   101	            throw notAllowed(reservation, "check in");
   102	        }
   103	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
   104	        store.update(reservation);
   105	        return reservation;
   106	    }
   107	
   108	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
   109	    public synchronized ReservationReceipt checkOut(long reservationId) {
   110	        Reservation reservation = find(reservationId);
   111	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   112	            throw notAllowed(reservation, "check out");
   113	        }
   114	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   115	        store.update(reservation);
   116	        return new ReservationReceipt(reservation, roomOf(reservation));
   117	    }
   118	
   119	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
   120	    public ReservationReceipt receiptCopy(long reservationId) {
   121	        Reservation reservation = find(reservationId);
   122	        if (!reservation.isPaid()) {
   123	            throw notAllowed(reservation, "issue a receipt for");
   124	        }
   125	        return new ReservationReceipt(reservation, roomOf(reservation));
   126	    }
   127	
   128	    private Room roomOf(Reservation reservation) {
   129	        return rooms.find(reservation.roomNumber()).orElseThrow();
   130	    }
   131	
   132	    private static HotelException notAllowed(Reservation reservation, String operation) {
   133	        return new HotelException(
   134	                ErrorCode.OPERATION_NOT_ALLOWED,
   135	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
   136	    }
   137	}
